import random
from collections import deque

def bfs_check_girth(adj, n):
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent[u]:
                    cl = dist[u] + dist[v] + 1
                    if cl < 7:
                        return False
    return True

n = 26
base = [(i, (i+1)%n) for i in range(n)]
poss = list({tuple(sorted((i, (i+d)%n))) for i in range(n) for d in [6,7,8,9,10,11,12,13]})

print('Possible chords:', len(poss))

random.seed(1)
found = False
sol = None
for trial in range(200):
    random.shuffle(poss)
    sel = []
    used = set()
    for e in poss:
        if e[0] not in used and e[1] not in used:
            sel.append(e)
            used |= {e[0], e[1]}
            if len(sel) == 13:
                break
    if len(sel) == 13:
        adj = [[] for _ in range(n)]
        for u,v in base + sel:
            adj[u].append(v)
            adj[v].append(u)
        if bfs_check_girth(adj, n):
            found = True
            sol = sorted(base + sel)
            break
print('Found:', found)
if found:
    print(sol)
